INSERT INTO area_packages (area_id, program, package_key, name_ar, name_en, name_fr, description_ar, description_en, description_fr, price, currency_code, billing_period, sessions_per_month, features_ar, features_en, features_fr, is_popular, is_active, sort_order) SELECT sa.id, CASE WHEN p.type IN ('quran','arabic') THEN p.type ELSE 'other' END, 'global-' || p.id, COALESCE(p.name_ar, 'باقة'), p.name_en, p.name_fr, NULL, NULL, NULL, p.price, 'USD', 'month', p.sessions, to_jsonb(string_to_array(COALESCE(p.features_ar,''), '،')), to_jsonb(string_to_array(COALESCE(p.features_en,''), ',')), to_jsonb(string_to_array(COALESCE(p.features_fr,''), ',')), p.popular, p.active, p.sort_order FROM site_areas sa CROSS JOIN packages p WHERE sa.slug='global' AND p.active=TRUE ON CONFLICT (area_id, package_key) DO UPDATE SET name_ar=EXCLUDED.name_ar, name_en=EXCLUDED.name_en, name_fr=EXCLUDED.name_fr, price=EXCLUDED.price, sessions_per_month=EXCLUDED.sessions_per_month, features_ar=EXCLUDED.features_ar, features_en=EXCLUDED.features_en, features_fr=EXCLUDED.features_fr, is_popular=EXCLUDED.is_popular, is_active=EXCLUDED.is_active, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-academy-1', 'ما هي أكاديمية الحافظ المتميز؟', 'What is Al-Hafiz Al-Mutamayez Academy?', 'Qu''est-ce que l''Academie Al-Hafiz Al-Mutamayez?', 'أكاديمية عالمية متخصصة في تحفيظ القرآن الكريم وتعليم التجويد وتأسيس اللغة العربية عبر الإنترنت، تضم نخبة من المعلمين المجازين من مختلف الدول العربية.', 'A global academy specializing in Quran memorization, Tajweed teaching, and Arabic language foundation online, with elite certified teachers from various Arab countries.', 'Une academie mondiale specialisee dans la memorisation du Coran, l''enseignement du Tajweed et les bases de la langue arabe en ligne.', 0 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-academy-2', 'هل الأكاديمية معتمدة رسمياً؟', 'Is the academy officially accredited?', 'L''academie est-elle officiellement accreditee?', 'نعم، معلمونا حاصلون على إجازات رسمية في القراءات والتجويد من شيوخ معتمدين، ونقدم شهادات إتمام للطلاب المنتهين من البرامج التعليمية.', 'Yes, our teachers hold official Ijazah certifications in Quranic recitations and Tajweed from accredited scholars, and we provide completion certificates.', 'Oui, nos enseignants detiennent des Ijazah officielles et nous fournissons des certificats d''achevement.', 1 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-academy-3', 'ما هي الفئات العمرية المستهدفة؟', 'What age groups do you serve?', 'Quels groupes d''age servez-vous?', 'نستقبل الرجال والنساء والأطفال والفتيات والشباب وجميع الأعمار من 4 سنوات فما فوق، مع معلمين ومعلمات وبرامج تناسب المستوى. نخدم الطلاب العرب والناطقين بالعربية في الخليج وأوروبا وأمريكا.', 'We accept all ages from 4 years and above. We have specialized programs for children, teenagers, and adults with age-appropriate methods.', 'Nous acceptons tous les ages a partir de 4 ans avec des programmes adaptes.', 2 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-academy-4', 'هل تقدمون خدماتكم لجميع الدول؟', 'Do you serve all countries?', 'Desservez-vous tous les pays?', 'نعم، نخدم الطلاب في جميع أنحاء العالم. لدينا طلاب من 30 دولة حول العالم بفضل التعليم عن بعد.', 'Yes, we serve students worldwide. We have students from over 30 countries thanks to online education.', 'Oui, nous servons des etudiants dans le monde entier, dans plus de 30 pays.', 3 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-academy-5', 'ما الذي يميز أكاديميتكم عن غيرها؟', 'What makes your academy unique?', 'Qu''est-ce qui rend votre academie unique?', 'نتميز بمعلمين مجازين، حصص فردية، مرونة في المواعيد، أسعار تنافسية، متابعة مستمرة للطالب، وتقارير شهرية لأولياء الأمور.', 'We stand out with certified teachers, individual sessions, flexible scheduling, competitive prices, continuous student follow-up, and monthly parent reports.', 'Enseignants certifies, cours individuels, horaires flexibles, prix competitifs et rapports mensuels.', 4 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-lessons-6', 'كم مدة الحصة الواحدة؟', 'How long is each session?', 'Quelle est la duree de chaque session?', 'مدة الحصة الواحدة 30 دقيقة، وهي المدة المثالية للتركيز والاستيعاب خاصة للأطفال.', 'Each session is 30 minutes, which is the ideal duration for focus and absorption, especially for children.', 'Chaque session dure 30 minutes, duree ideale pour la concentration.', 5 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-lessons-7', 'هل الحصص فردية أم جماعية؟', 'Are sessions individual or group?', 'Les sessions sont-elles individuelles ou en groupe?', 'جميع حصصنا فردية (One-on-One) لضمان أعلى جودة تعليمية وتركيز كامل على الطالب.', 'All our sessions are individual (One-on-One) to ensure the highest quality education and full focus on the student.', 'Toutes nos sessions sont individuelles pour la meilleure qualite.', 6 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-lessons-8', 'ما هي المنصة المستخدمة للدروس؟', 'What platform is used for lessons?', 'Quelle plateforme est utilisee?', 'نستخدم منصة Zoom أو Google Meet للدروس المباشرة مع إمكانية مشاركة الشاشة والسبورة التفاعلية.', 'We use Zoom or Google Meet for live lessons with screen sharing and interactive whiteboard capabilities.', 'Nous utilisons Zoom ou Google Meet avec partage d''ecran et tableau blanc.', 7 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-lessons-9', 'هل يمكنني تغيير موعد الحصة؟', 'Can I change the session time?', 'Puis-je changer l''heure de la session?', 'نعم، يمكنك تغيير الموعد بإبلاغنا قبل 24 ساعة على الأقل من موعد الحصة عبر واتساب أو التواصل مع الإدارة.', 'Yes, you can change the time by notifying us at least 24 hours before the session via WhatsApp or contacting administration.', 'Oui, en nous prevenant au moins 24 heures avant via WhatsApp.', 8 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-lessons-10', 'ماذا لو فاتتني حصة؟', 'What if I miss a session?', 'Que se passe-t-il si je manque une session?', 'في حالة الإبلاغ المسبق (قبل 24 ساعة) يتم تعويض الحصة. أما في حالة الغياب بدون إبلاغ مسبق فتُحسب من رصيد الباقة.', 'With prior notice (24 hours), the session is rescheduled. Without notice, it counts from your package balance.', 'Avec preavis de 24h, la session est reprogrammee. Sans preavis, elle est deductee.', 9 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-packages-11', 'ما هي الباقات المتاحة للقرآن الكريم؟', 'What Quran packages are available?', 'Quels forfaits Coran sont disponibles?', 'لدينا ثلاث باقات: باقة 4 حصص بـ 15$، وباقة 8 حصص بـ 28$، وباقة 12 حصة بـ 42$، وكل حصة مدتها 30 دقيقة.', 'We have three packages: 4 sessions for $15, 8 sessions for $28, and 12 sessions for $42, each session is 30 minutes.', 'Trois forfaits: 4 sessions a 15$, 8 sessions a 28$, et 12 sessions a 42$.', 10 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-packages-12', 'ما هي باقات تأسيس اللغة العربية؟', 'What Arabic language packages are available?', 'Quels forfaits de langue arabe sont disponibles?', 'باقة 4 حصص بـ 20$، وباقة 8 حصص بـ 36$، وباقة 12 حصة بـ 54$، وتشمل القراءة والكتابة والإملاء.', '4 sessions for $20, 8 sessions for $36, and 12 sessions for $54, including reading, writing, and spelling.', '4 sessions a 20$, 8 sessions a 36$, et 12 sessions a 54$.', 11 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-packages-13', 'هل يمكنني تجربة حصة مجانية قبل الاشتراك؟', 'Can I try a free session before subscribing?', 'Puis-je essayer une session gratuite?', 'نعم، نقدم حصة تجريبية مجانية للطلاب الجدد لتعريفهم بالمنهج وطريقة التعليم وتقييم مستواهم.', 'Yes, we offer a free trial session for new students to introduce our curriculum and assess their level.', 'Oui, nous offrons une session d''essai gratuite pour les nouveaux etudiants.', 12 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-packages-14', 'ما هي طرق الدفع المتاحة؟', 'What payment methods are available?', 'Quels modes de paiement sont disponibles?', 'نقبل الدفع عبر PayPal، التحويل البنكي، فودافون كاش، وخدمات تحويل الأموال المحلية والدولية.', 'We accept PayPal, bank transfer, Vodafone Cash, and local/international money transfer services.', 'PayPal, virement bancaire, Vodafone Cash et services de transfert.', 13 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-packages-15', 'هل هناك خصومات للأشقاء؟', 'Are there sibling discounts?', 'Y a-t-il des reductions pour les freres et soeurs?', 'نعم، نقدم خصم 10% عند اشتراك أخوين أو أكثر، وخصومات خاصة للعائلات الكبيرة.', 'Yes, we offer 10% discount for two or more siblings, with special discounts for large families.', 'Oui, 10% de reduction pour deux freres/soeurs ou plus.', 14 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-teachers-16', 'هل المعلمون مجازون؟', 'Are teachers certified?', 'Les enseignants sont-ils certifies?', 'نعم، جميع معلمينا حاصلون على إجازات في القراءات القرآنية والتجويد من شيوخ معتمدين، بالإضافة إلى خبرة تعليمية لا تقل عن 3 سنوات.', 'Yes, all our teachers hold Ijazah in Quranic recitations and Tajweed from accredited scholars, with at least 3 years teaching experience.', 'Oui, tous nos enseignants ont des Ijazah avec au moins 3 ans d''experience.', 15 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-teachers-17', 'هل يمكنني اختيار المعلم/المعلمة؟', 'Can I choose my teacher?', 'Puis-je choisir mon enseignant?', 'نعم، يمكنك اختيار المعلم أو المعلمة حسب رغبتك، ونقدم معلمات متخصصات للطالبات والأطفال.', 'Yes, you can choose your preferred teacher. We offer female teachers for female students and children.', 'Oui, avec des enseignantes pour les etudiantes et les enfants.', 16 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-teachers-18', 'هل يمكن تغيير المعلم إذا لم أكن راضياً؟', 'Can I change my teacher if unsatisfied?', 'Puis-je changer d''enseignant?', 'بالتأكيد، راحة الطالب أولوية عندنا. يمكنك طلب تغيير المعلم في أي وقت وسنوفر لك البديل المناسب.', 'Absolutely, student satisfaction is our priority. You can request a teacher change anytime and we''ll provide a suitable alternative.', 'Absolument, vous pouvez demander un changement a tout moment.', 17 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-teachers-19', 'هل المعلمون يتحدثون لغات أخرى؟', 'Do teachers speak other languages?', 'Les enseignants parlent-ils d''autres langues?', 'لدينا معلمون يتحدثون العربية والإنجليزية والفرنسية والأوردية لخدمة الطلاب من مختلف الجنسيات.', 'We have teachers who speak Arabic, English, French, and Urdu to serve students from various nationalities.', 'Nos enseignants parlent arabe, anglais, francais et ourdou.', 18 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-curriculum-20', 'ما هو المنهج المتبع في تحفيظ القرآن؟', 'What is the Quran memorization curriculum?', 'Quel est le programme de memorisation?', 'نتبع منهجية شاملة تجمع بين الحفظ التدريجي مع التجويد، والمراجعة الدورية، والتفسير المبسط، مع مراعاة قدرات كل طالب.', 'We follow a comprehensive methodology combining gradual memorization with Tajweed, periodic review, simplified interpretation, tailored to each student''s abilities.', 'Methodologie complete avec memorisation progressive, Tajweed et revision periodique.', 19 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-curriculum-21', 'ما هو منهج تأسيس اللغة العربية؟', 'What is the Arabic foundation curriculum?', 'Quel est le programme de langue arabe?', 'نعتمد على مناهج تفاعلية حديثة تشمل: تعلم الحروف وأشكالها، الحركات، القراءة، الكتابة، الإملاء، والتعبير بأساليب ممتعة وجذابة.', 'We use modern interactive curricula including: letter forms, vowels, reading, writing, spelling, and expression with fun and engaging methods.', 'Programmes interactifs modernes: lettres, voyelles, lecture, ecriture et expression.', 20 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-curriculum-22', 'هل تقدمون دروس تفسير القرآن؟', 'Do you offer Quran interpretation lessons?', 'Offrez-vous des cours d''interpretation?', 'نعم، نقدم تفسيراً مبسطاً للآيات ضمن حصص الحفظ لمساعدة الطالب على فهم معاني ما يحفظه.', 'Yes, we provide simplified interpretation of verses within memorization sessions to help students understand what they memorize.', 'Oui, interpretation simplifiee integree aux sessions de memorisation.', 21 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-curriculum-23', 'هل هناك اختبارات دورية؟', 'Are there periodic tests?', 'Y a-t-il des tests periodiques?', 'نعم، نجري اختبارات شهرية لتقييم مستوى الطالب ونرسل تقارير مفصلة لأولياء الأمور عن تقدم أبنائهم.', 'Yes, we conduct monthly tests to evaluate student level and send detailed progress reports to parents.', 'Oui, tests mensuels avec rapports detailles aux parents.', 22 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-curriculum-24', 'هل تعلمون القراءات العشر؟', 'Do you teach the ten Qira''at?', 'Enseignez-vous les dix Qira''at?', 'نعم، لدينا معلمون متخصصون في القراءات العشر للطلاب المتقدمين الراغبين في إتقان القراءات المختلفة.', 'Yes, we have specialized teachers in the ten Qira''at for advanced students who wish to master different recitations.', 'Oui, pour les etudiants avances souhaitant maitriser les differentes recitations.', 23 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-technical-25', 'ما هي المتطلبات التقنية للحصص؟', 'What are the technical requirements?', 'Quelles sont les exigences techniques?', 'تحتاج إلى: جهاز كمبيوتر أو تابلت أو هاتف ذكي، اتصال إنترنت مستقر، سماعات أو مكبر صوت، وتطبيق Zoom أو Google Meet.', 'You need: a computer, tablet, or smartphone, stable internet connection, headphones or speaker, and Zoom or Google Meet app.', 'Ordinateur/tablette/smartphone, internet stable, ecouteurs, et Zoom ou Google Meet.', 24 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-technical-26', 'هل أحتاج كاميرا؟', 'Do I need a camera?', 'Ai-je besoin d''une camera?', 'يُفضل وجود كاميرا لتفاعل أفضل مع المعلم، لكنها ليست إلزامية. بعض الطالبات يفضلن التعلم بدون كاميرا ونحترم ذلك.', 'A camera is preferred for better interaction, but not mandatory. Some female students prefer learning without a camera and we respect that.', 'Preferee mais pas obligatoire. Certaines etudiantes preferent sans camera.', 25 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-technical-27', 'هل تسجلون الحصص؟', 'Do you record sessions?', 'Enregistrez-vous les sessions?', 'يمكن تسجيل الحصص بناءً على طلب الطالب أو ولي الأمر للمراجعة لاحقاً، مع الحفاظ على الخصوصية التامة.', 'Sessions can be recorded upon student or parent request for later review, with full privacy maintained.', 'Sur demande pour revision, avec respect total de la vie privee.', 26 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-technical-28', 'ماذا لو انقطع الإنترنت أثناء الحصة؟', 'What if internet disconnects during a session?', 'Et si internet se deconnecte?', 'في حالة انقطاع الإنترنت يتم استئناف الحصة فور عودة الاتصال، وإذا ضاع وقت كبير يتم تعويض الطالب.', 'The session resumes when connection returns. If significant time is lost, the student is compensated.', 'La session reprend apres la reconnexion. Compensation si perte significative.', 27 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-certificates-29', 'هل تقدمون شهادات إتمام؟', 'Do you provide completion certificates?', 'Fournissez-vous des certificats?', 'نعم، نقدم شهادات إتمام للطلاب الذين ينهون برامج الحفظ أو التأسيس، بالإضافة إلى إجازات للطلاب المتميزين.', 'Yes, we provide completion certificates for students who finish memorization or foundation programs, plus Ijazah for outstanding students.', 'Oui, certificats d''achevement et Ijazah pour les etudiants distingues.', 28 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-certificates-30', 'هل الإجازة معتمدة؟', 'Is the Ijazah accredited?', 'L''Ijazah est-elle accreditee?', 'نعم، الإجازات التي نقدمها تكون بسند متصل إلى النبي صلى الله عليه وسلم، وهي معتمدة عند أهل العلم والقراءات.', 'Yes, our Ijazah comes with a connected chain (Isnad) to the Prophet (PBUH), recognized by scholars of Quranic recitations.', 'Oui, avec une chaine connectee (Isnad) au Prophete, reconnue par les savants.', 29 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-followup-31', 'كيف يمكنني متابعة تقدم طفلي؟', 'How can I track my child''s progress?', 'Comment suivre les progres de mon enfant?', 'نرسل تقارير شهرية مفصلة لأولياء الأمور عبر واتساب أو البريد الإلكتروني تتضمن مستوى الحفظ والتجويد وعدد الجلسات التفاعلية المباشرة المكتملة عبر الإنترنت والسلوك.', 'We send detailed monthly reports to parents via WhatsApp or email covering memorization level, Tajweed, number of completed direct interactive online sessions, and behavior.', 'Rapports mensuels detailles via WhatsApp ou email incluant les sessions en ligne completees.', 30 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-followup-32', 'هل هناك تواصل مع المعلم خارج أوقات الحصص؟', 'Is there communication with the teacher outside sessions?', 'Y a-t-il communication en dehors des sessions?', 'نعم، يمكن لأولياء الأمور التواصل مع المعلم أو الإدارة عبر واتساب للاستفسار عن مستوى الطالب أو أي ملاحظات.', 'Yes, parents can communicate with the teacher or administration via WhatsApp for student progress inquiries or any notes.', 'Oui, via WhatsApp pour les questions sur les progres.', 31 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-followup-33', 'ماذا يحدث إذا لم يحرز طفلي تقدماً؟', 'What if my child is not making progress?', 'Et si mon enfant ne progresse pas?', 'نقوم بتقييم الوضع وتغيير الاستراتيجية التعليمية أو المعلم إذا لزم الأمر. هدفنا ضمان تقدم كل طالب حسب قدراته.', 'We evaluate the situation and change teaching strategy or teacher if needed. Our goal is to ensure every student progresses.', 'Evaluation et changement de strategie si necessaire.', 32 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-34', 'كيف يمكنني الاشتراك؟', 'How can I subscribe?', 'Comment puis-je m''inscrire?', 'يمكنك الاشتراك عبر التواصل معنا على واتساب أو تيليجرام أو من خلال صفحة "اتصل بنا" في الموقع وسنرد عليك خلال ساعات.', 'You can subscribe by contacting us on WhatsApp, Telegram, or through the "Contact Us" page on our website. We''ll respond within hours.', 'Via WhatsApp, Telegram ou la page "Contactez-nous". Reponse en quelques heures.', 33 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-35', 'هل يمكن للكبار الاشتراك؟', 'Can adults subscribe?', 'Les adultes peuvent-ils s''inscrire?', 'بالتأكيد! لدينا برامج مخصصة للكبار تناسب مستوياتهم وأهدافهم سواء في حفظ القرآن أو تعلم التجويد أو تعلم العربية.', 'Absolutely! We have specialized programs for adults suitable for their levels and goals in Quran memorization, Tajweed, or Arabic.', 'Absolument! Programmes specialises pour adultes.', 34 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-36', 'هل تقدمون دورات مكثفة في رمضان؟', 'Do you offer intensive Ramadan courses?', 'Offrez-vous des cours intensifs pendant le Ramadan?', 'نعم، نقدم برامج مكثفة خاصة في شهر رمضان تشمل مراجعة شاملة وحفظ مكثف وحلقات تلاوة جماعية.', 'Yes, we offer special intensive programs during Ramadan including comprehensive review, intensive memorization, and group recitation sessions.', 'Oui, programmes intensifs pendant le Ramadan avec revision et memorisation.', 35 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-37', 'هل يمكن الاشتراك في أكثر من باقة؟', 'Can I subscribe to more than one package?', 'Puis-je souscrire a plusieurs forfaits?', 'نعم، يمكنك الجمع بين باقة القرآن وباقة تأسيس العربي معاً، وتحصل على خصم خاص عند الاشتراك في باقتين.', 'Yes, you can combine Quran and Arabic packages, with a special discount for subscribing to both.', 'Oui, avec une reduction speciale pour deux forfaits.', 36 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-38', 'ما هي أوقات العمل المتاحة؟', 'What are the available working hours?', 'Quels sont les horaires disponibles?', 'نعمل على مدار الأسبوع من الساعة 8 صباحاً حتى 11 مساءً بتوقيت القاهرة، مع مرونة في ترتيب المواعيد حسب المنطقة الزمنية.', 'We operate all week from 8 AM to 11 PM Cairo time, with flexibility in scheduling based on your timezone.', 'De 8h a 23h heure du Caire, tous les jours, avec flexibilite.', 37 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-39', 'هل يمكنني إيقاف الاشتراك مؤقتاً؟', 'Can I pause my subscription?', 'Puis-je suspendre mon abonnement?', 'نعم، يمكنك تجميد الاشتراك لمدة تصل إلى أسبوعين في حالات السفر أو المرض أو الظروف الخاصة بالتنسيق مع الإدارة.', 'Yes, you can freeze your subscription for up to two weeks for travel, illness, or special circumstances by coordinating with administration.', 'Oui, suspension jusqu''a deux semaines pour voyage ou maladie.', 38 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-40', 'هل هناك سياسة استرداد الأموال؟', 'Is there a refund policy?', 'Y a-t-il une politique de remboursement?', 'نعم، يمكن استرداد المبلغ خلال أول 3 أيام من الاشتراك إذا لم يبدأ الطالب أي حصة، أو تعويض بحصص إضافية.', 'Yes, refund is available within the first 3 days if no sessions have started, or compensation with additional sessions.', 'Remboursement dans les 3 premiers jours si aucune session n''a commence.', 39 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-41', 'كيف يمكنني التواصل مع الإدارة؟', 'How can I contact administration?', 'Comment contacter l''administration?', 'يمكنك التواصل معنا عبر: واتساب (اضغط الزر أدناه)، تيليجرام (@acabemy_quraan)، أو البريد الإلكتروني (enamel311@gmail.com).', 'Contact us via: WhatsApp (use the button below), Telegram (@acabemy_quraan), or email (enamel311@gmail.com).', 'WhatsApp (bouton ci-dessous), Telegram (@acabemy_quraan), ou email (enamel311@gmail.com).', 40 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-42', 'هل تقدمون دورات في العقيدة والفقه؟', 'Do you offer Aqeedah and Fiqh courses?', 'Offrez-vous des cours de Aqeedah et Fiqh?', 'حالياً نركز على تحفيظ القرآن والتجويد وتأسيس اللغة العربية، ونخطط لإضافة دورات في العقيدة والفقه قريباً.', 'Currently we focus on Quran memorization, Tajweed, and Arabic foundation. We plan to add Aqeedah and Fiqh courses soon.', 'Actuellement, nous nous concentrons sur le Coran et l''arabe. Cours de Aqeedah et Fiqh bientot.', 41 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-43', 'هل يمكنني حضور حصة تجريبية مع طفلي؟', 'Can I attend a trial session with my child?', 'Puis-je assister a une session d''essai avec mon enfant?', 'نعم، نرحب بحضور أولياء الأمور في الحصة التجريبية الأولى للاطمئنان على جودة التعليم وطريقة التدريس.', 'Yes, parents are welcome to attend the first trial session to observe the quality of teaching and methods.', 'Oui, les parents sont les bienvenus a la premiere session d''essai.', 42 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-44', 'هل يوجد حد أقصى لعدد الحصص أسبوعياً؟', 'Is there a maximum number of weekly sessions?', 'Y a-t-il un maximum de sessions par semaine?', 'لا يوجد حد أقصى، يمكنك ترتيب الحصص حسب رغبتك ضمن الباقة المشترك بها، سواء يومياً أو عدة مرات أسبوعياً.', 'No maximum limit. You can arrange sessions as you wish within your package, daily or several times a week.', 'Pas de limite. Organisez selon vos preferences.', 43 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-45', 'هل تقدمون مسابقات قرآنية؟', 'Do you offer Quran competitions?', 'Organisez-vous des concours coraniques?', 'نعم، ننظم مسابقات قرآنية دورية مع جوائز تحفيزية للطلاب المتميزين لتشجيعهم على الحفظ والتلاوة.', 'Yes, we organize periodic Quran competitions with incentive prizes for outstanding students.', 'Oui, concours periodiques avec prix pour les etudiants distingues.', 44 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-46', 'هل تقبلون الطلاب غير الناطقين بالعربية؟', 'Do you accept non-Arabic speaking students?', 'Acceptez-vous les non-arabophones?', 'نعم، لدينا معلمون متخصصون في تعليم القرآن والعربية لغير الناطقين بها باستخدام مناهج مبسطة وفعالة.', 'Yes, we have specialized teachers for non-Arabic speakers using simplified and effective curricula.', 'Oui, avec des enseignants specialises pour les non-arabophones.', 45 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-47', 'ما هي مدة صلاحية الباقة؟', 'What is the package validity period?', 'Quelle est la validite du forfait?', 'صلاحية الباقة شهر واحد من تاريخ الاشتراك، ويمكن تمديدها في حالات خاصة بالتنسيق مع الإدارة.', 'Package validity is one month from subscription date, extendable in special cases by coordinating with administration.', 'Validite d''un mois, prolongeable dans des cas speciaux.', 46 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-48', 'هل يمكن حضور الحصة من الهاتف المحمول؟', 'Can I attend from a mobile phone?', 'Puis-je assister depuis un telephone?', 'نعم، يمكنك الحضور من أي جهاز: كمبيوتر، تابلت، أو هاتف ذكي. لكننا ننصح بالتابلت أو الكمبيوتر لتجربة أفضل.', 'Yes, from any device. We recommend a tablet or computer for a better experience.', 'Oui, depuis tout appareil. Tablette ou ordinateur recommande.', 47 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-49', 'هل تقدمون محتوى تعليمي مجاني؟', 'Do you offer free educational content?', 'Offrez-vous du contenu gratuit?', 'نعم، نوفر في قسم المكتبة كتباً ومواد تعليمية مجانية، بالإضافة إلى ألعاب ومسابقات تعليمية تفاعلية على الموقع.', 'Yes, our Library section has free books and materials, plus interactive educational games and quizzes on the website.', 'Oui, livres gratuits dans la bibliotheque et jeux educatifs sur le site.', 48 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'global-faq-general-50', 'هل هناك برنامج خاص لذوي الاحتياجات الخاصة؟', 'Is there a special program for special needs?', 'Y a-t-il un programme pour les besoins speciaux?', 'نعم، لدينا معلمون مدربون على التعامل مع ذوي الاحتياجات الخاصة بصبر واحترافية مع مناهج مخصصة.', 'Yes, we have teachers trained to work with special needs students with patience and professionalism using customized curricula.', 'Oui, enseignants formes pour les besoins speciaux avec des programmes personnalises.', 49 FROM site_areas WHERE slug='global' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, question_en=EXCLUDED.question_en, question_fr=EXCLUDED.question_fr, answer_ar=EXCLUDED.answer_ar, answer_en=EXCLUDED.answer_en, answer_fr=EXCLUDED.answer_fr, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'germany-faq-1', 'هل تناسب الحصص الأطفال المقيمين في ألمانيا؟', 'هل تناسب الحصص الأطفال المقيمين في ألمانيا؟', NULL, 'نعم، الحصص الفردية مناسبة للأطفال والشباب والبالغين، مع خطة ومدة تناسب العمر والمستوى.', 'نعم، الحصص الفردية مناسبة للأطفال والشباب والبالغين، مع خطة ومدة تناسب العمر والمستوى.', NULL, 0 FROM site_areas WHERE slug='germany' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
