INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'germany-faq-4', 'هل يوجد خصم للأخوة؟', 'هل يوجد خصم للأخوة؟', NULL, 'نعم، يوجد خصم خاص للأخوة، وتُعرف التفاصيل عند التواصل عبر WhatsApp.', 'نعم، يوجد خصم خاص للأخوة، وتُعرف التفاصيل عند التواصل عبر WhatsApp.', NULL, 3 FROM site_areas WHERE slug='germany' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'germany-faq-5', 'هل يمكن اختيار معلم أو معلمة؟', 'هل يمكن اختيار معلم أو معلمة؟', NULL, 'يمكن ذكر التفضيل عند الحجز، وسننسق حسب التوفر والبرنامج المناسب.', 'يمكن ذكر التفضيل عند الحجز، وسننسق حسب التوفر والبرنامج المناسب.', NULL, 4 FROM site_areas WHERE slug='germany' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'germany-faq-6', 'هل يبدأ الطالب من الصفر في تحفيظ القرآن؟', 'هل يبدأ الطالب من الصفر في تحفيظ القرآن؟', NULL, 'نعم، نبدأ من المستوى الحالي للطالب مع خطة للحفظ والتسميع والمراجعة وتصحيح التلاوة عند توفره.', 'نعم، نبدأ من المستوى الحالي للطالب مع خطة للحفظ والتسميع والمراجعة وتصحيح التلاوة عند توفره.', NULL, 5 FROM site_areas WHERE slug='germany' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'germany-faq-7', 'هل يبدأ الطالب من الحروف في تأسيس اللغة العربية؟', 'هل يبدأ الطالب من الحروف في تأسيس اللغة العربية؟', NULL, 'نعم، يمكن البدء من الحروف أو تقييم المستوى والانتقال إلى القراءة والكتابة والنطق.', 'نعم، يمكن البدء من الحروف أو تقييم المستوى والانتقال إلى القراءة والكتابة والنطق.', NULL, 6 FROM site_areas WHERE slug='germany' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
INSERT INTO area_faq_items (area_id, question_key, question_ar, question_en, question_fr, answer_ar, answer_en, answer_fr, sort_order) SELECT id, 'germany-faq-8', 'هل تشمل حصة العربية القراءة والكتابة والنطق؟', 'هل تشمل حصة العربية القراءة والكتابة والنطق؟', NULL, 'نعم، يحدد البرنامج المهارات المطلوبة ويجمع بينها تدريجياً وفق مستوى الطالب.', 'نعم، يحدد البرنامج المهارات المطلوبة ويجمع بينها تدريجياً وفق مستوى الطالب.', NULL, 7 FROM site_areas WHERE slug='germany' ON CONFLICT (area_id, question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar, answer_ar=EXCLUDED.answer_ar, sort_order=EXCLUDED.sort_order, updated_at=NOW();
